import { useState } from "react"
import { UploadManager } from "@/components/rhoe/upload-manager/upload-manager"

export function UploadDocuments() {
  return <UploadManager accept="image/*,.pdf" onUpload={async ({ file, signal }) => {
    const body = new FormData()
    body.append("file", file)
    const response = await fetch("/api/upload", { method: "POST", body, signal })
    if (!response.ok) throw new Error("Upload failed")
  }} />
}

// Keep files in memory until your form is submitted.
export function LocalUpload() {
  const [files, setFiles] = useState<File[]>([])
  async function submit() {
    const body = new FormData()
    files.forEach(file => body.append("files", file))
    const response = await fetch("/api/upload", { method: "POST", body })
    if (!response.ok) throw new Error("Upload failed")
  }
  return <form onSubmit={event => { event.preventDefault(); void submit() }}>
    <UploadManager uploadMode="local" onFilesChange={setFiles} />
    <button type="submit">Upload files</button>
  </form>
}

